create table if not exists public.fastapply_applicant_sync (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,job_profile_id uuid not null references public.job_profiles(id) on delete cascade,external_id text not null,resume_id uuid references public.resumes(id) on delete set null,remote_resume_id text,profile_synced_at timestamptz,resume_synced_at timestamptz,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,job_profile_id),unique(external_id));
alter table public.fastapply_applicant_sync enable row level security;grant select,insert,update,delete on public.fastapply_applicant_sync to authenticated;drop policy if exists "Users manage own FastApply applicant sync" on public.fastapply_applicant_sync;create policy "Users manage own FastApply applicant sync" on public.fastapply_applicant_sync for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
alter table public.ai_agent_configs add column if not exists platforms text[] not null default array['greenhouse','lever','ashby','workable'],add column if not exists date_posted text not null default 'past_week',add column if not exists max_applications_per_day integer not null default 10,add column if not exists schedule_type text not null default 'daily',add column if not exists schedule_time text not null default '09:00',add column if not exists schedule_days integer[] not null default '{}';alter table public.ai_agent_configs drop constraint if exists ai_agent_configs_max_applications_per_day_check;alter table public.ai_agent_configs add constraint ai_agent_configs_max_applications_per_day_check check(max_applications_per_day between 1 and 100);
alter table public.applications add column if not exists remote_application_id text,add column if not exists remote_automation_id text,add column if not exists platform text,add column if not exists remote_status text;create index if not exists fastapply_applicant_sync_user_idx on public.fastapply_applicant_sync(user_id);create index if not exists applications_remote_automation_idx on public.applications(remote_automation_id) where remote_automation_id is not null;
